var personas = [
 {label:"Life Risikoleben flow", persona:"You are a German speaking customer wanting Lebensversicherung, specifically Risikoleben. Reply briefly. Provide when asked: Alter 35, Versicherungssumme 200000 Euro, Laufzeit 25 Jahre, Nichtraucher. You want the estimate now, no specialist. Name Anna Berger, phone 0676 1112223. After the price and closing, say Danke and end."},
 {label:"Haushalt Plus flow", persona:"You are a German speaking customer wanting Haushaltsversicherung. Reply briefly. Provide when asked: Versicherungssumme 50000 Euro, Ort Graz, Tarif Plus, Alarmanlage ja. You want the estimate now. Name Peter Mayer, phone 0660 9998887. After the price and closing, say Danke and end."},
 {label:"Krankenversicherung handoff", persona:"You are a German speaking customer asking for Krankenversicherung (health insurance). Reply briefly. When the agent says it is handled by a specialist and asks for your details, agree and give name Lukas Huber, phone 0664 5556667. Then say Danke and end."},
 {label:"Kfz Haftpflicht only flow", persona:"You are a German speaking customer wanting Kfz insurance, only Haftpflicht, no Kasko. Reply briefly. Provide when asked: nur Haftpflicht, Alter 60, 66 kW, Ort Linz, ein Lenker, 20 schadenfreie Jahre. You want the estimate now. Name Eva Gruber, phone 0676 3334445. After the price and closing, say Danke and end."}
];
return personas.map(function(p){ return { json: p }; });

var items=$input.all(); var out=[];
for(var r=0;r<items.length;r++){
 var conv=items[r].json.simulated_conversation||[];
 var agentQ=[], tools=[];
 for(var i=0;i<conv.length;i++){ var t=conv[i]; if(t.role==="agent" && t.message) agentQ.push(t.message); if(t.tool_calls){ for(var j=0;j<t.tool_calls.length;j++){ var p={}; try{p=JSON.parse(t.tool_calls[j].params_as_json||"{}");}catch(e){} tools.push(p); } } }
 out.push({ json: { idx:r+1, agent_turns:agentQ, tool_params:tools } });
}
return out;
